async () => {
  await document.fonts.ready;
  const card = document.getElementById('card');
  const cr = card.getBoundingClientRect();
  const out = {card:[cr.width,cr.height], fontLoaded: document.fonts.check('700 56px Inter'), items:[]};
  card.querySelectorAll('.header,.speaker,.avatar,.name,.role,.title,.meta,.cta,.inner').forEach(el=>{
    const r = el.getBoundingClientRect();
    out.items.push({c:el.className, x:Math.round(r.x), y:Math.round(r.y), w:Math.round(r.width), h:Math.round(r.height), bottom:Math.round(r.bottom), right:Math.round(r.right)});
  });
  return out;
}

