async () => {
  await document.fonts.ready;
  const card = document.getElementById('card');
  const o=[];
  card.querySelectorAll('.header,.body,.col,.side,.avatar,.name,.role,.title,.meta,.cta').forEach(el=>{
    const r=el.getBoundingClientRect();
    o.push(el.className+' x'+Math.round(r.x)+' y'+Math.round(r.y)+' w'+Math.round(r.width)+' h'+Math.round(r.height)+' b'+Math.round(r.bottom)+' r'+Math.round(r.right));
  });
  o.push('scroll '+card.scrollWidth+'x'+card.scrollHeight);
  return o;
}

