async () => {
  await document.fonts.ready;
  const t = document.querySelector('.title');
  const res = {};
  for (const fs of [64,66,68,70,72]) {
    t.style.fontSize = fs+'px';
    const r = new Range(); 
    // measure lines via client rects of text nodes
    const rng = document.createRange(); rng.selectNodeContents(t);
    res[fs] = {h: Math.round(t.getBoundingClientRect().height), rects: rng.getClientRects().length};
  }
  t.style.fontSize='';
  return res;
}

