async () => {
  const load = src => new Promise(r=>{const i=new Image();i.onload=()=>r(src+': '+i.naturalWidth+'x'+i.naturalHeight);i.onerror=()=>r(src+': ERR');i.src=src+'?t='+Date.now();});
  return Promise.all([load('square.png'),load('landscape.png'),load('story.png')]);
}
